    const fileRef = useRef<HTMLInputElement>(null);
    const [videos, setVideos] = useState<VideoItem[]>([]);
    const [selected, setSelected] = useState<string | null>(null);
    const [isLoading, setIsLoading] = useState(false);
    const [uploads, setUploads] = useState<UploadItem[]>([]);
    const [isDragging, setIsDragging] = useState(false);
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        if (!open) return;
        setSelected(null);
        setError(null);
        setIsLoading(true);
        listUploadedVideosAction(slug).then((result) => {
            setIsLoading(false);
            if ("error" in result) {
                setError(result.error);
                return;
            }
            setVideos(result.videos);
        });
    }, [open, slug]);

    const handleFiles = (files: File[]) => {
        setError(null);
        for (const file of files) {
            const id = Math.random().toString(36).slice(2);
            setUploads((prev) => [...prev, { id, name: file.name, progress: 0 }]);

            const formData = new FormData();
            formData.append("file", file);

            const xhr = new XMLHttpRequest();
            xhr.open("POST", `/api/upload-video/${slug}`);

            xhr.upload.addEventListener("progress", (e) => {
                if (e.lengthComputable) {
                    setUploads((prev) =>
                        prev.map((u) =>
                            u.id === id
                                ? { ...u, progress: Math.round((e.loaded / e.total) * 100) }
                                : u
                        )
                    );
                }
            });

            xhr.addEventListener("load", () => {
                setUploads((prev) => prev.filter((u) => u.id !== id));
                try {
                    const result = JSON.parse(xhr.responseText) as
                        { url: string } | { error: string };
                    if ("error" in result) {
                        setError(result.error);
                        return;
                    }
                    setVideos((prev) => [{ url: result.url, name: file.name }, ...prev]);
                    setSelected(result.url);
                } catch {
                    setError("Upload failed, please try again");
                }
            });

            xhr.addEventListener("error", () => {
                setUploads((prev) => prev.filter((u) => u.id !== id));
                setError("Upload failed, please try again");
            });

            xhr.send(formData);
        }
    };

    return (
        <Modal
            open={open}
            onClose={onClose}
            title="Select Video"
            size="xl"
            footer={
                <div className="flex w-full justify-end gap-3">
                    <Button type="button" variant="secondary" onClick={onClose}>
                        Cancel
