"use client";

import { useEffect, useMemo, useState } from "react";
import NextStepButton from "@/components/NextStepButton";
import { HbdContent } from "@/components/sections/utils/content-types";

type SceneItem = {
    id: number;
    x: number;
    y: number;
    size: number;
    emoji: string;
    isTarget: boolean;
    rotate: number;
};

const WORLD_WIDTH = 960;
const WORLD_HEIGHT = 560;
const ROUND_TIME = 12;
const TOTAL_ROUNDS = 3;

const DECO_EMOJIS = ["🎈", "🎂", "✨", "🧸", "💖", "🌟", "🍬", "🎀", "☁️"];
const TARGET_EMOJI = "🎁";

function randomBetween(min: number, max: number) {
    return Math.random() * (max - min) + min;
}

function shuffleArray<T>(array: T[]) {
    const copied = [...array];
    for (let i = copied.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [copied[i], copied[j]] = [copied[j], copied[i]];
    }
    return copied;
}

function createScene(round: number) {
    const itemCount = 18 + round * 4;
    const isMobile = typeof window !== "undefined" ? window.innerWidth < 640 : false;

    const items: SceneItem[] = [];

    for (let i = 0; i < itemCount; i++) {
        const emoji = DECO_EMOJIS[Math.floor(Math.random() * DECO_EMOJIS.length)];

        items.push({
            id: i + 1,
            x: randomBetween(24, WORLD_WIDTH - 80),
            y: randomBetween(24, WORLD_HEIGHT - 90),
            size: isMobile ? randomBetween(24, 42) : randomBetween(28, 54),
            emoji,
            isTarget: false,
            rotate: randomBetween(-18, 18),
        });
    }

    items.push({
        id: itemCount + 1,
        x: randomBetween(24, WORLD_WIDTH - 80),
        y: randomBetween(24, WORLD_HEIGHT - 90),
        size: isMobile ? randomBetween(30, 42) : randomBetween(34, 50),
        emoji: TARGET_EMOJI,
        isTarget: true,
        rotate: randomBetween(-12, 12),
    });

    return shuffleArray(items);
}

export default function FindTheHiddenGift({
    nextStep,
}: {
    nextStep: () => void;
    content: HbdContent;
}) {
    const [round, setRound] = useState(1);
    const [timeLeft, setTimeLeft] = useState(ROUND_TIME);
    const [sceneItems, setSceneItems] = useState<SceneItem[]>([]);
    const [foundCount, setFoundCount] = useState(0);
    const [mistakeCount, setMistakeCount] = useState(0);
    const [status, setStatus] = useState<"playing" | "round-clear" | "finished" | "failed">(
        "playing"
    );
    const [message, setMessage] = useState("Find the hidden gift 🎁");
    const [highlightTarget, setHighlightTarget] = useState(false);

    useEffect(() => {
        if (status !== "playing") return;

        const timer = setInterval(() => {
            setTimeLeft((prev) => {
                if (prev <= 1) {
                    clearInterval(timer);
                    setStatus("failed");
                    setHighlightTarget(true);
                    setMessage("Time's up! The gift was here 🎁");
                    return 0;
                }
                return prev - 1;
            });
        }, 1000);

        return () => clearInterval(timer);
    }, [status, round]);

    useEffect(() => {
        if (status === "playing") {
            setSceneItems(createScene(round));
            setTimeLeft(ROUND_TIME);
            setHighlightTarget(false);
            setMessage(`Round ${round}: Find the hidden gift 🎁`);
        }
    }, [round, status]);

    useEffect(() => {
        setSceneItems(createScene(1));
    }, []);

    const accuracy = useMemo(() => {
        const totalClicks = foundCount + mistakeCount;
        if (totalClicks === 0) return 100;
        return Math.round((foundCount / totalClicks) * 100);
    }, [foundCount, mistakeCount]);

    const handleClickItem = (item: SceneItem) => {
        if (status !== "playing") return;

        if (item.isTarget) {
            setFoundCount((prev) => prev + 1);
            setMessage("Found it! 🎉");
            setHighlightTarget(true);

            if (round >= TOTAL_ROUNDS) {
                setStatus("finished");
            } else {
                setStatus("round-clear");
            }
        } else {
            setMistakeCount((prev) => prev + 1);
            setMessage("Not this one, keep looking 💗");
        }
    };

    const handleNextRound = () => {
        if (round < TOTAL_ROUNDS) {
            setRound((prev) => prev + 1);
            setStatus("playing");
        }
    };

    const handleRestart = () => {
        setRound(1);
        setTimeLeft(ROUND_TIME);
        setFoundCount(0);
        setMistakeCount(0);
        setStatus("playing");
        setHighlightTarget(false);
        setMessage("Find the hidden gift 🎁");
        setSceneItems(createScene(1));
    };

    return (
        <section className="mx-auto w-full max-w-6xl rounded-[24px] border border-(--theme-border) bg-linear-to-br from-white via-(--theme-softer) to-(--theme-soft) p-3 shadow-xl sm:rounded-[32px] sm:p-6">
            <div className="mb-4 flex flex-col gap-4 rounded-[20px] bg-white/85 p-4 shadow-sm sm:mb-5 sm:rounded-[24px] sm:p-5 md:flex-row md:items-center md:justify-between">
                <div>
                    <p className="text-[11px] font-semibold uppercase tracking-[0.16em] text-(--theme-primary) sm:text-sm sm:tracking-[0.2em]">
                        Birthday Mini Game
                    </p>
                    <h2 className="text-2xl font-bold text-slate-800 sm:text-3xl">
                        Find the Hidden Gift 🎁
                    </h2>
                    <p className="mt-2 text-xs text-slate-600 sm:text-sm">
                        Click to find the gift hidden among the decorations
                    </p>
                    <p className="mt-1 text-[11px] text-slate-500 sm:text-xs">
                        {TOTAL_ROUNDS} rounds, {ROUND_TIME} seconds each
                    </p>
                </div>

                <div className="grid grid-cols-2 gap-3 sm:flex sm:flex-wrap sm:items-center">
                    <div className="rounded-2xl bg-(--theme-soft) px-4 py-3 text-center">
                        <p className="text-[11px] text-(--theme-primary-dark) sm:text-xs">Round</p>
                        <p className="text-xl font-bold text-(--theme-primary-dark) sm:text-2xl">
                            {Math.min(round, TOTAL_ROUNDS)}/{TOTAL_ROUNDS}
                        </p>
                    </div>

                    <div className="rounded-2xl bg-(--theme-soft) px-4 py-3 text-center">
                        <p className="text-[11px] text-(--theme-primary-dark) sm:text-xs">Found</p>
                        <p className="text-xl font-bold text-(--theme-primary-dark) sm:text-2xl">
                            {foundCount}
                        </p>
                    </div>

                    <div className="rounded-2xl bg-sky-100 px-4 py-3 text-center">
                        <p className="text-[11px] text-sky-700 sm:text-xs">Accuracy</p>
                        <p className="text-xl font-bold text-sky-600 sm:text-2xl">{accuracy}%</p>
                    </div>

                    <div className="rounded-2xl bg-violet-100 px-4 py-3 text-center">
